 46	     * Builds the policy from a list like {@code address-validation,archive-copy:normal,test-redirect:test}. Each item
 47	     * is a rule name (address-validation, archive-copy) with an optional scope (always, test, normal). Rules not
 48	     * listed are off. A null or blank list means the standard policy.
 49	     */
 50	    public static EmailPolicy forRules(boolean testMode, String configured) {
 51	        Map<String, Scope> defaults = new LinkedHashMap<>();
 52	        defaults.put("address-validation", Scope.ALWAYS);
 53	        defaults.put("archive-copy", Scope.NORMAL_MODE_ONLY);
 54	        Map<String, Scope> chosen = new LinkedHashMap<>();
 55	        if (configured == null || configured.isBlank()) {
 56	            chosen.putAll(defaults);
 57	        } else {
 58	            for (String item : configured.split(",")) {
 59	                String[] parts = item.trim().split(":", 2);
 60	                String name = parts[0].trim();
 61	                if (name.equals("test-redirect")) {
 62	                    continue; // always on in test mode
 63	                }
 64	                if (!defaults.containsKey(name)) {
 65	                    throw new IllegalArgumentException("unknown e-mail rule: " + name);
 66	                }
 67	                chosen.put(name, parts.length == 1 ? defaults.get(name) : scopeNamed(parts[1].trim()));
 68	            }
 69	        }
 70	        EmailPolicy policy = new EmailPolicy(testMode);
 71	        Scope validation = chosen.get("address-validation");
 72	        if (validation != null) {
 73	            policy.with(EmailRules.addressValidation(), validation);
 74	        }
 75	        policy.with(EmailRules.testRedirect(), Scope.TEST_MODE_ONLY);
 76	        Scope archive = chosen.get("archive-copy");
 77	        if (archive != null) {
 78	            policy.with(EmailRules.archiveCopy(), archive);
 79	        }
 80	        return policy;
 81	    }
 82	
 83	    private static Scope scopeNamed(String name) {
 84	        return switch (name) {
 85	            case "always" -> Scope.ALWAYS;
 86	            case "test" -> Scope.TEST_MODE_ONLY;
 87	            case "normal" -> Scope.NORMAL_MODE_ONLY;
 88	            default -> throw new IllegalArgumentException("unknown e-mail rule scope: " + name);
 89	        };
 90	    }
 91	
 92	    List<OutgoingMessage> apply(OutgoingMessage message) {
 93	        List<OutgoingMessage> current = List.of(message);
 94	        for (Entry entry : entries) {
 95	            if (!entry.scope().covers(testMode)) {
 96	                continue;
 97	            }
 98	            List<OutgoingMessage> next = new ArrayList<>();
 99	            for (OutgoingMessage each : current) {
100	                next.addAll(entry.rule().apply(each));
101	            }
102	            current = next;
103	        }
104	        return current;
105	    }
